// Page-27 portion of the T3j table, on the combined overlay (Z + central-edge).
// Help text is asserted separately from the page header. A missing control step,
// a failed comparison, and a screenshot error stop the run.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/accept_page_k1.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from './zone_session_k1.mjs';
import { applyStep, capture } from './observe_k1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/accept_page_k1.mjs om-emu\n');
  process.exit(2);
}
const table = JSON.parse(readFileSync(resolve('work/scripts/accept_table_k1.json'), 'utf8'));
const lines = [];
let stopped = false;
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify(row));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(resolve('work/out/accept-k1.jsonl'), lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
const USE_RE = /use\('([^']+)'\)/g;

function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}
function shaFile(file) {
  const data = readFileSync(file);
  return { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}
function moduleInventory() {
  const seeds = [
    resolve('work/scripts/accept_page_k1.mjs'),
    resolve('work/scripts/observe_k1.mjs'),
    resolve('work/scripts/zone_session_k1.mjs'),
  ];
  const zoneText = readFileSync(resolve('work/scripts/zone_session_k1.mjs'), 'utf8');
  USE_RE.lastIndex = 0;
  let found;
  while ((found = USE_RE.exec(zoneText))) seeds.push(resolve('om-emu/emu', found[1]));
  const seen = new Map();
  const queue = [...seeds];
  while (queue.length) {
    const file = queue.pop();
    if (seen.has(file) || !existsSync(file)) continue;
    const data = readFileSync(file);
    seen.set(file, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
    const text = data.toString('utf8');
    IMPORT_RE.lastIndex = 0;
    let match;
    while ((match = IMPORT_RE.exec(text))) {
      const next = resolveSpec(file, match[1]);
      if (next && !seen.has(next)) queue.push(next);
    }
  }
  const resources = [
    'inputs/00_0100_50000020.decoded.bin',
    'inputs/02_0106_458c0020.decoded.bin',
    'work/out/overlay-combined-k1.csv',
    'work/scripts/accept_table_k1.json',
  ].filter((path) => existsSync(resolve(path))).map((path) => ({ path, ...shaFile(resolve(path)) }));
  const modules = [...seen.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([file, rec]) => ({
    path: file.replaceAll('\\', '/'),
    sha256: rec.sha256,
    bytes: rec.bytes,
  }));
  return { modules, resources };
}

function wantOf(step, role) {
  const rb = step.expect.readback;
  const control = role === 'control';
  return {
    title: step.expect.title,
    helpText: step.expect.helpText,
    highlight: step.expect.highlight,
    invariant: step.expect.invariant,
    readback: {
      profile: control ? rb.profileControl : rb.profile,
      profileCached: control ? rb.profileCachedControl : rb.profileCached,
      k90a1: rb.k90a1,
      screen: rb.screen,
      slotValue: rb.slotValue,
      helpId: rb.helpId,
      glyph: control ? (rb.glyphControl ?? null) : rb.glyph,
      cells: rb.cells ?? null,
    },
  };
}

function judge(step, got, role, previous, controlGot) {
  const want = wantOf(step, role);
  const rb = want.readback;
  const problems = [];
  if (got.title !== want.title) problems.push('title');
  if (got.helpText !== want.helpText) problems.push('helpText');
  if (got.highlight !== want.highlight) problems.push('highlight');
  if (got.screen !== rb.screen) problems.push('screen');
  if (got.profile !== rb.profile) problems.push('profile');
  if (got.profileCached !== rb.profileCached) problems.push('profileCached');
  if (!same(got.invariant.k90a1, rb.k90a1)) problems.push('k90a1');
  if (got.slotValue !== rb.slotValue) problems.push('slotValue');
  if (got.helpId !== rb.helpId) problems.push('helpId');
  if (!same(got.glyph, rb.glyph)) problems.push('glyph');
  if (rb.cells && !same(got.invariant, rb.cells)) problems.push('cells');
  if (step.expect.invariant && previous && !same(got.invariant, previous)) problems.push('invariant');
  let controlSame = null;
  if (role === 'candidate' && step.controlStep) {
    if (!controlGot) {
      problems.push('control-missing');
    } else {
      controlSame = got.title === controlGot.title
        && got.helpText === controlGot.helpText
        && got.highlight === controlGot.highlight
        && got.screen === controlGot.screen
        && same(got.invariant, controlGot.invariant);
      if (!controlSame) problems.push('control');
    }
  }
  return { pass: problems.length === 0, problems, want };
}

const controlGot = new Map();
function record(session, role, step, got, previous) {
  if (step.controlStep && role === 'candidate' && !controlGot.has(step.controlStep)) {
    const row = {
      session, id: step.id, key: step.key, pass: false,
      problems: ['control-unresolved'],
      controlStep: step.controlStep,
      screenshot: got.screenshot,
    };
    emit(row);
    return false;
  }
  const judged = judge(step, got, role, previous, role === 'candidate' ? controlGot.get(step.controlStep) : null);
  emit({
    session,
    id: step.id,
    key: step.key,
    action: step.action,
    pass: judged.pass,
    problems: judged.problems,
    expected: judged.want,
    actual: {
      title: got.title,
      helpText: got.helpText,
      highlight: got.highlight,
      texts: got.texts,
      screen: got.screen,
      profile: got.profile,
      profileCached: got.profileCached,
      k90a1: got.invariant.k90a1,
      slotValue: got.slotValue,
      helpId: got.helpId,
      glyph: got.glyph,
      cells: got.invariant,
      screenshot: got.screenshot,
    },
    screenshot: got.screenshot,
    controlStep: step.controlStep,
  });
  if (role === 'control') controlGot.set(step.id, got);
  return judged.pass;
}

async function runLane(name, role) {
  const steps = table.filter((step) => role === 'candidate' || step.shared);
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-k1-' + name + '.jsonl',
    tag: 'accept-k1-' + name,
    candidate: role === 'candidate',
    help: true,
    rowLabel: true,
    overlayCsv: role === 'candidate' ? 'work/out/overlay-combined-k1.csv' : null,
    fatalShots: true,
    explanation: role === 'candidate'
      ? 'Combined Z and central-edge. Page-27 portion. Bring-up and idle-120b are in this session. The profile source is still the legacy AF Home provider. Role: behaviour.'
      : 'Stock control for the shared page-27 steps. Bring-up and idle-120b, no AF-ON overlay.',
    change: role === 'candidate' ? 'combined: Z bytes, central-edge, owned block relocated' : 'none',
    async drive(ctx) {
      const brought = ctx.bringUp();
      ctx.emit('behaviour', { step: 'bring-up', label: 'EMULATOR-ONLY native bring-up 0x6071181e, 0x608fe1b0, 0x609df7e4, task 105. Role: behaviour.', ...brought });
      let previous = null;
      for (const step of steps) {
        const got = await applyStep(ctx, step);
        const ok = record(name, role, step, got, previous);
        previous = got.invariant;
        if (!ok) throw new Error('assertion failed at ' + name + ' ' + step.id);
      }
    },
  });
  if (!result.ok) {
    stopped = true;
    emit({ record: 'session-failed', session: name, error: result.failed });
  }
  return result.ok;
}

const inventory = moduleInventory();
writeFileSync(resolve('work/out/import-inventory-k1.json'), JSON.stringify({
  note: 'SHA-256 taken before the page-27 sessions start.',
  hashed: 'execution',
  ...inventory,
}, null, 2) + '\n');
emit({ record: 'import-inventory', hashed: 'execution', modules: inventory.modules.length, resources: inventory.resources.length });

try {
  for (const [name, role] of [['control', 'control'], ['c1', 'candidate'], ['c2', 'candidate']]) {
    if (stopped) break;
    await runLane(name, role);
  }
  emit({ record: 'done', ok: !stopped });
  if (stopped) process.exitCode = 1;
} catch (e) {
  emit({ record: 'done', ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exitCode = 1;
}
